    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1

    background = max(counts, key=counts.get)
    marker = next(value for value in counts if value not in (background, 0))
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == marker]
    min_r = min(r for r, c in cells)
    max_r = max(r for r, c in cells)
    min_c = min(c for r, c in cells)
    max_c = max(c for r, c in cells)
    shape = [(r - min_r, c - min_c) for r, c in cells]

    out = [row[:] for row in grid]
    for top in range(h - (max_r - min_r + 1) + 1):
        for left in range(w - (max_c - min_c + 1) + 1):
            if all(grid[top + r][left + c] == 0 for r, c in shape):
                for r, c in shape:
                    out[top + r][left + c] = marker
    return out
